window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f86b3144b9bbb812"]={"versions": [{"id": "FIG-f86b3144b9bbb812", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellen-Architekturdiagramm (<code>cmp ArchitectureView-DeterministicClient</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Interaktionskanäle zwischen einer deterministisch ausgeführten Adaptive Application und dem Functional Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht die Entkopplung von Prozess-Lebenszyklussteuerung, deterministischer Zeit-/Ressourcenkontrolle und Statusrückmeldung über die C++-Sprachbindung von <code>ara::exec</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Komponenten</p>\n<ul class=\"fig-list\">\n<li><strong><code>Application</code>:</strong> POSIX-Prozessinstanz der Adaptive Application, welche deterministische Ausführungsgarantien (z. B. für sicherheitskritische Regelschleifen, Sensorfusion) benötigt.</li>\n<li><strong><code>Execution Management</code>:</strong> Plattform-Dienst (<code>ara::exec</code>), zuständig für Prozessinstanziierung, State-Management, Ressourcenkontrolle und Scheduling gemäß Execution Manifest.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenklassen & Entitäten (<code>«ara::exec»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Schnittstelle zur Kapselung von deterministischer Zeit, Synchronisation und Nebenläufigkeit:</li>\n<li><code>+ GetActivationTime()</code>: Liefert den logischen Ausführungszeitstempel des aktuellen Zyklus.</li>\n<li><code>+ GetNextActivationTime()</code>: Liefert die logische Zeit der nächsten Zyklusaktivierung.</li>\n<li><code>+ GetRandom()</code>: Liefert deterministische Pseudozufallswerte (reproduzierbare Seed-Folge pro Durchlauf).</li>\n<li><code>+ RunWorkerPool()</code>: Triggert die deterministische Abarbeitung nebenläufiger Work-Packages innerhalb des Worker-Pools.</li>\n<li><code>+ WaitForNextActivation()</code>: Blockiert den Thread bis zum Beginn des nächsten deterministischen Zyklus.</li>\n<li><strong><code>ApplicationClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung:</li>\n<li><code>+ ReportApplicationState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>) an das Execution Management.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Interaktionen</p>\n<ul class=\"fig-list\">\n<li><strong>Port-Bindungen:</strong></li>\n<li><code>Application</code> nutzt (Required Interface / Socket) <code>DeterministicClient</code> und <code>ApplicationClient</code>.</li>\n<li><code>Execution Management</code> stellt (Provided Interface / Ball) beide Schnittstellen bereit; die <code>«ara::exec»</code>-Klassen fungieren als Applikations-seitige API-Proxys.</li>\n<li><strong>Prozess-Kontrollpfad:</strong></li>\n<li>Gerichtete Steuerungsbeziehung (<code>Start / Terminate</code>) direkt von <code>Execution Management</code> auf <code>Application</code> (POSIX-Signale/Prozesssteuerung wie <code>fork</code>/<code>exec</code>, <code>SIGTERM</code>/<code>SIGKILL</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Startup:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> startet den Prozess der <code>Application</code> gemäß Startup-Konfiguration.</li>\n<li><code>Application</code> instanziiert <code>ApplicationClient</code> und meldet via <code>ReportApplicationState(kRunning)</code> Betriebsbereitschaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deterministische Zyklusschleife:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Application</code> fragt logische Zeitstempel via <code>GetActivationTime()</code> bzw. <code>GetNextActivationTime()</code> ab (keine Abfrage der POSIX-Systemuhr <code>CLOCK_REALTIME</code>, um Jitter und Nicht-Determinismus zu verhindern).</li>\n<li>Falls stochastische Algorithmen benötigt werden: Abruf reproduzierbarer Werte über <code>GetRandom()</code>.</li>\n<li>Parallele Berechnungsabschnitte werden deterministisch gebündelt via <code>RunWorkerPool()</code> synchronisiert ausgeführt.</li>\n<li>Nach Abschluss der Berechnungen ruft die Applikation <code>WaitForNextActivation()</code> auf; Execution Management reaktiviert den Thread erst zum nächsten deterministischen Ausführungsfenster.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Initiiert durch <code>Execution Management</code> (<code>Start / Terminate</code>), woraufhin die Applikation den Shutdown einleitet und ggf. per <code>ReportApplicationState(kTerminating)</code> quittiert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag für Deterministische Applikationen:</strong></li>\n<li>Direkte Aufrufe von OS-Zeitquellen (<code>std::chrono::system_clock</code>, <code>clock_gettime</code>), POSIX-Threads (<code>pthread_create</code>, <code>std::thread</code>) oder Standard-Zufallsgeneratoren (<code>rand()</code>) sind strikt verboten, da sie den Nachweis deterministischer Wiederholbarkeit (Record & Replay) brechen. Stattdessen sind zwingend die Methoden von <code>ara::exec::DeterministicClient</code> zu verwenden.</li>\n<li><strong>Konfigurations- & Manifest-Bindung:</strong></li>\n<li>Die Verwendung des <code>DeterministicClient</code> erfordert entsprechende Konfigurationen im <em>Execution Manifest</em> (z. B. Definition von Cycle Times, WorkerPool-Größen und CPU-Affinities).</li>\n<li><strong>Fehlerbehandlung & Timeouts:</strong></li>\n<li>Überschreitet die Abarbeitung vor <code>WaitForNextActivation()</code> das im Manifest definierte Ausführungsbudget (Execution Budget Violation), greift das Execution Management über konfigurierte Recovery-Aktionen (z. B. Benachrichtigung des <em>Health Management</em> <code>ara::phm</code> oder Prozess-Terminierung) ein.</li>\n</ul>"}, {"id": "FIG-dde84b401c43a841", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellen-Architekturdiagramm (<code>cmp ArchitectureView-DeterministicClient</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Interaktionskanäle zwischen einer deterministisch ausgeführten Adaptive Application und dem Functional Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht die Entkopplung von Prozess-Lebenszyklussteuerung, deterministischer Zeit-/Ressourcenkontrolle und Statusrückmeldung über die C++-Sprachbindung von <code>ara::exec</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Komponenten</p>\n<ul class=\"fig-list\">\n<li><strong><code>Application</code>:</strong> POSIX-Prozessinstanz der Adaptive Application, welche deterministische Ausführungsgarantien (z. B. für sicherheitskritische Regelschleifen, Sensorfusion) benötigt.</li>\n<li><strong><code>Execution Management</code>:</strong> Plattform-Dienst (<code>ara::exec</code>), zuständig für Prozessinstanziierung, State-Management, Ressourcenkontrolle und Scheduling gemäß Execution Manifest.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenklassen & Entitäten (<code>«ara::exec»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Schnittstelle zur Kapselung von deterministischer Zeit, Synchronisation und Nebenläufigkeit:</li>\n<li><code>+ GetActivationTime()</code>: Liefert den logischen Ausführungszeitstempel des aktuellen Zyklus.</li>\n<li><code>+ GetNextActivationTime()</code>: Liefert die logische Zeit der nächsten Zyklusaktivierung.</li>\n<li><code>+ GetRandom()</code>: Liefert deterministische Pseudozufallswerte (reproduzierbare Seed-Folge pro Durchlauf).</li>\n<li><code>+ RunWorkerPool()</code>: Triggert die deterministische Abarbeitung nebenläufiger Work-Packages innerhalb des Worker-Pools.</li>\n<li><code>+ WaitForNextActivation()</code>: Blockiert den Thread bis zum Beginn des nächsten deterministischen Zyklus.</li>\n<li><strong><code>ExecutionClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung:</li>\n<li><code>+ ReportExecutionState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>) an das Execution Management.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Interaktionen</p>\n<ul class=\"fig-list\">\n<li><strong>Port-Bindungen:</strong></li>\n<li><code>Application</code> nutzt (Required Interface / Socket) <code>DeterministicClient</code> und <code>ExecutionClient</code>.</li>\n<li><code>Execution Management</code> stellt (Provided Interface / Ball) beide Schnittstellen bereit; die <code>«ara::exec»</code>-Klassen fungieren als Applikations-seitige API-Proxys.</li>\n<li><strong>Prozess-Kontrollpfad:</strong></li>\n<li>Gerichtete Steuerungsbeziehung (<code>Start / Terminate</code>) direkt von <code>Execution Management</code> auf <code>Application</code> (POSIX-Signale/Prozesssteuerung wie <code>fork</code>/<code>exec</code>, <code>SIGTERM</code>/<code>SIGKILL</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Startup:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> startet den Prozess der <code>Application</code> gemäß Startup-Konfiguration.</li>\n<li><code>Application</code> instanziiert <code>ExecutionClient</code> und meldet via <code>ReportExecutionState(kRunning)</code> Betriebsbereitschaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deterministische Zyklusschleife:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Application</code> fragt logische Zeitstempel via <code>GetActivationTime()</code> bzw. <code>GetNextActivationTime()</code> ab (keine Abfrage der POSIX-Systemuhr <code>CLOCK_REALTIME</code>, um Jitter und Nicht-Determinismus zu verhindern).</li>\n<li>Falls stochastische Algorithmen benötigt werden: Abruf reproduzierbarer Werte über <code>GetRandom()</code>.</li>\n<li>Parallele Berechnungsabschnitte werden deterministisch gebündelt via <code>RunWorkerPool()</code> synchronisiert ausgeführt.</li>\n<li>Nach Abschluss der Berechnungen ruft die Applikation <code>WaitForNextActivation()</code> auf; Execution Management reaktiviert den Thread erst zum nächsten deterministischen Ausführungsfenster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Deterministische Ausführung (<code>DeterministicClient</code>):</strong></li>\n<li>Entwickler deterministischer Applikationen dürfen keine direkten OS-Zeitgeber oder Standard-Zufallsgeneratoren nutzen; Zeitfortschritt und Pseudozufallszahlen müssen zwingend über <code>GetActivationTime()</code>, <code>GetNextActivationTime()</code> und <code>GetRandom()</code> bezogen werden.</li>\n<li>Nebenläufige Threads innerhalb des deterministischen Kontexts müssen über <code>RunWorkerPool()</code> koordiniert werden, um deterministisches Scheduling sicherzustellen.</li>\n<li>Die Zyklusgrenze wird explizit durch <code>WaitForNextActivation()</code> synchronisiert.</li>\n<li><strong>Prozess-Zustandsverwaltung (<code>ExecutionClient</code>):</strong></li>\n<li>Jede Adaptive Application muss ihren Lebenszyklus- und Ausführungsstatus über <code>ReportExecutionState()</code> an das Execution Management übermitteln, um Timeout-Überwachungen und Zustandsübergänge des Gesamtsystems zu ermöglichen.</li>\n</ul>"}, {"id": "FIG-256312eb0428c727", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellen-Architekturdiagramm (<code>cmp ArchitectureView-DeterministicClient</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Interaktionskanäle zwischen einer deterministisch ausgeführten Adaptive Application und dem Functional Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht die Entkopplung von Prozess-Lebenszyklussteuerung, deterministischer Zeit-/Ressourcenkontrolle und Statusrückmeldung über die C++-Sprachbindung von <code>ara::exec</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Komponenten</p>\n<ul class=\"fig-list\">\n<li><strong><code>Application</code>:</strong> POSIX-Prozessinstanz der Adaptive Application, welche deterministische Ausführungsgarantien (z. B. für sicherheitskritische Regelschleifen, Sensorfusion) benötigt.</li>\n<li><strong><code>Execution Management</code>:</strong> Plattform-Dienst (<code>ara::exec</code>), zuständig für Prozessinstanziierung, State-Management, Ressourcenkontrolle und Scheduling gemäß Execution Manifest.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenklassen & Entitäten (<code>«ara::exec»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Schnittstelle zur Kapselung von deterministischer Zeit, Synchronisation und Nebenläufigkeit:</li>\n<li><code>+ GetActivationTime()</code>: Liefert den logischen Ausführungszeitstempel des aktuellen Zyklus.</li>\n<li><code>+ GetNextActivationTime()</code>: Liefert die logische Zeit der nächsten Zyklusaktivierung.</li>\n<li><code>+ GetRandom()</code>: Liefert deterministische Pseudozufallswerte (reproduzierbare Seed-Folge pro Durchlauf).</li>\n<li><code>+ RunWorkerPool()</code>: Triggert die deterministische Abarbeitung nebenläufiger Work-Packages innerhalb des Worker-Pools.</li>\n<li><code>+ WaitForNextActivation()</code>: Blockiert den Thread bis zum Beginn des nächsten deterministischen Zyklus.</li>\n<li><strong><code>ExecutionClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung:</li>\n<li><code>+ ReportExecutionState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>) an das Execution Management.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Interaktionen</p>\n<ul class=\"fig-list\">\n<li><strong>Port-Bindungen:</strong></li>\n<li><code>Application</code> nutzt (Required Interface / Socket) <code>DeterministicClient</code> und <code>ExecutionClient</code>.</li>\n<li><code>Execution Management</code> stellt (Provided Interface / Ball) beide Schnittstellen bereit; die <code>«ara::exec»</code>-Klassen fungieren als Applikations-seitige API-Proxys.</li>\n<li><strong>Prozess-Kontrollpfad:</strong></li>\n<li>Gerichtete Steuerungsbeziehung (<code>Start / Terminate</code>) direkt von <code>Execution Management</code> auf <code>Application</code> (POSIX-Signale/Prozesssteuerung wie <code>fork</code>/<code>exec</code>, <code>SIGTERM</code>/<code>SIGKILL</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Startup:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> startet den Prozess der <code>Application</code> gemäß Startup-Konfiguration.</li>\n<li><code>Application</code> instanziiert <code>ExecutionClient</code> und meldet via <code>ReportExecutionState(kRunning)</code> Betriebsbereitschaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deterministische Zyklusschleife:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Application</code> fragt logische Zeitstempel via <code>GetActivationTime()</code> bzw. <code>GetNextActivationTime()</code> ab (keine Abfrage der POSIX-Systemuhr <code>CLOCK_REALTIME</code>, um Jitter und Nicht-Determinismus zu verhindern).</li>\n<li>Falls stochastische Algorithmen benötigt werden: Abruf reproduzierbarer Werte über <code>GetRandom()</code>.</li>\n<li>Parallele Berechnungsabschnitte werden deterministisch gebündelt via <code>RunWorkerPool()</code> synchronisiert ausgeführt.</li>\n<li>Nach Abschluss der Berechnungen ruft die Applikation <code>WaitForNextActivation()</code> auf; Execution Management reaktiviert den Thread erst zum nächsten deterministischen Ausführungsfenster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Deterministische Ausführung (<code>DeterministicClient</code>):</strong></li>\n<li>Entwickler deterministischer Applikationen dürfen keine direkten OS-Zeitgeber oder Standard-Zufallsgeneratoren nutzen; Zeitfortschritt und Pseudozufallszahlen müssen zwingend über <code>GetActivationTime()</code>, <code>GetNextActivationTime()</code> und <code>GetRandom()</code> bezogen werden.</li>\n<li>Nebenläufige Threads innerhalb des deterministischen Kontexts müssen über <code>RunWorkerPool()</code> koordiniert werden, um deterministisches Scheduling sicherzustellen.</li>\n<li>Die Zyklusgrenze wird explizit durch <code>WaitForNextActivation()</code> synchronisiert.</li>\n<li><strong>Prozess-Zustandsverwaltung (<code>ExecutionClient</code>):</strong></li>\n<li>Jede Adaptive Application muss ihren Lebenszyklus- und Ausführungsstatus über <code>ReportExecutionState()</code> an das Execution Management übermitteln, um Timeout-Überwachungen und Zustandsübergänge des Gesamtsystems zu ermöglichen.</li>\n</ul>"}], "trans": [{"from": "FIG-f86b3144b9bbb812", "to": "FIG-dde84b401c43a841", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Klasse und Schnittstelle <code>ApplicationClient</code>:</strong> Umbenannt zu <code>ExecutionClient</code>.</li>\n<li><strong>Methode <code>ReportApplicationState()</code>:</strong> Umbenannt zu <code>ReportExecutionState()</code>.</li>\n<li><strong>Port-Bezeichner:</strong> Die oberen und unteren Port-Beschriftungen der Schnittstelle wurden von <code>ApplicationClient</code> zu <code>ExecutionClient</code> geändert.</li>\n</ul>"}, {"from": "FIG-dde84b401c43a841", "to": "FIG-256312eb0428c727", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
